<?php
namespace Tests;
use App\Services\{ImageUploads,SalonStore,Tenant};
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Storage};
use Illuminate\Http\UploadedFile;
final class ImageUploadsTest extends TestCase {
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'||config('database.connections.sqlite.database')!==':memory:')throw new \RuntimeException('In-memory database only.');Artisan::call('migrate',['--force'=>true]);DB::table('salon_state')->delete();DB::table('media_assets')->delete();DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode(SalonStore::initial())]);app(Tenant::class)->id=1;Storage::fake('local');$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('i',40)])->withHeader('X-CSRF-TOKEN',str_repeat('i',40));}
 private function png(int $w=1800,int $h=900):string{$im=imagecreatetruecolor($w,$h);imagealphablending($im,false);imagesavealpha($im,true);imagefill($im,0,0,imagecolorallocatealpha($im,20,80,150,50));ob_start();imagepng($im);$png=ob_get_clean();imagedestroy($im);return $png;}
 public function test_every_target_is_resized_to_its_own_limit_with_aspect_ratio_and_alpha_preserved():void{foreach(['logo'=>800,'avatar'=>800,'staff'=>1000,'service'=>1000,'cover'=>1500,'photo'=>1500] as $target=>$limit){$output=ImageUploads::process($this->png(),$target);$info=getimagesizefromstring($output);$this->assertSame($limit,$info[0]);$this->assertSame((int)($limit/2),$info[1]);$this->assertSame(IMAGETYPE_WEBP,$info[2]);$image=imagecreatefromstring($output);$this->assertGreaterThan(0,(imagecolorat($image,0,0)>>24)&127);imagedestroy($image);}$small=getimagesizefromstring(ImageUploads::process($this->png(120,60),'cover'));$this->assertSame([120,60],array_slice($small,0,2));}
 public function test_replacing_and_deleting_a_picture_reclaims_only_unreferenced_own_assets():void{$first=$this->post('/api/media',['target'=>'cover','image'=>UploadedFile::fake()->createWithContent('cover.png',$this->png())],['Accept'=>'application/json'])->assertCreated()->json('url');$asset=DB::table('media_assets')->first();$this->assertSame(1500,getimagesize(Storage::disk('local')->path($asset->path))[0]);$this->post('/api/media',['target'=>'cover','image'=>UploadedFile::fake()->createWithContent('cover.png',$this->png(300,200))],['Accept'=>'application/json'])->assertCreated();Storage::disk('local')->assertMissing($asset->path);$this->assertSame(1,DB::table('media_assets')->count());$next=DB::table('media_assets')->first();$url=app(SalonStore::class)->read()['profile']['cover'];$this->deleteJson('/api/media',['target'=>'cover','url'=>$url])->assertOk();Storage::disk('local')->assertMissing($next->path);$this->assertSame(0,DB::table('media_assets')->count());}
 public function test_invalid_or_excessive_images_are_rejected_before_being_stored():void{$this->post('/api/media',['target'=>'cover','image'=>UploadedFile::fake()->createWithContent('image.png','<script>bad</script>')],['Accept'=>'application/json'])->assertUnprocessable();$this->post('/api/media',['target'=>'cover','image'=>UploadedFile::fake()->image('wide.png',6001,1)],['Accept'=>'application/json'])->assertUnprocessable();$this->assertSame(0,DB::table('media_assets')->count());$this->assertSame([],Storage::disk('local')->allFiles());}
 public function test_reminder_disable_preserves_data_and_hides_events_and_default_szep_is_off():void{$s=app(SalonStore::class)->read();$this->assertNotContains('szep',$s['settings']['prepaymentMethods']);$id=$this->postJson('/api/provider-reminders',['title'=>'Rendelés','staffId'=>'anna','startsAt'=>'2036-05-07T10:00','duration'=>15,'frequency'=>'weekly','count'=>0])->assertOk()->json('id');app(SalonStore::class)->mutate(function(&$s){$s['settings']['providerRemindersEnabled']=false;});$this->getJson('/api/provider-reminders?from=2036-05-01&to=2036-05-31')->assertExactJson(['reminders'=>[],'occurrences'=>[]]);$this->deleteJson('/api/provider-reminders/'.$id)->assertUnprocessable();$this->assertSame(1,DB::table('provider_reminders')->where('id',$id)->count());app(SalonStore::class)->mutate(function(&$s){$s['settings']['providerRemindersEnabled']=true;});$this->getJson('/api/provider-reminders?from=2036-05-01&to=2036-05-31')->assertOk()->assertJsonPath('reminders.0.id',$id);}
 public function test_an_image_still_referenced_in_the_gallery_is_not_deleted_by_cover_replacement():void{$url=$this->post('/api/media',['target'=>'cover','image'=>UploadedFile::fake()->createWithContent('cover.png',$this->png(120,60))],['Accept'=>'application/json'])->assertCreated()->json('url');$asset=DB::table('media_assets')->first();app(SalonStore::class)->mutate(function(&$s)use($url){$s['profile']['photos']=[$url];});$this->post('/api/media',['target'=>'cover','image'=>UploadedFile::fake()->createWithContent('new.png',$this->png(100,50))],['Accept'=>'application/json'])->assertCreated();Storage::disk('local')->assertExists($asset->path);$this->assertSame(2,DB::table('media_assets')->count());$this->get('/media/'.$asset->id)->assertOk();}

}
